 def eq(name,a,b,yes,no):P(name).branch({1:yes},no,[('C64U',a,b)])
 regs=('mg_node','mg_i','mg_count','mg_end','mg_id','mg_tag','mg_attr','mg_payload','mg_top')
 P('MG.fail').a(E.rej('not covered: signature graph equality budget')).goto(fail)
